import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { URL } from 'url';

const app = express();
app.use(express.json());

// Environment-dependent configuration
const TRUSTED_DOMAINS = (process.env.TRUSTED_DOMAINS || 'example.com,api.example.com').split(',');
const NORMALIZATION_FORM = process.env.UNICODE_NORM || 'NFC';
const STRICT_MODE = process.env.STRICT_MODE === 'true';

interface DeeplinkRequest {
  target_url: string;
  user_id: string;
  callback_token: string;
}

function generateHMAC(data: string, secret: string): string {
  return crypto.createHmac('sha256', secret).update(data).digest('hex');
}

// Domain validation utility
function extractDomain(url: string): string {
  try {
    const parsed = new URL(url);
    return parsed.hostname;
  } catch {
    return '';
  }
}

// Normalize domain for comparison - handles internationalized domain names
function normalizeDomain(domain: string): string {
  // Apply Unicode normalization to handle equivalent representations
  const normalized = domain.normalize(NORMALIZATION_FORM as any);
  // Convert to lowercase for case-insensitive comparison
  return normalized.toLowerCase();
}

// Check if a character is a standard ASCII letter/digit/hyphen/dot
function isStandardDomainChar(ch: string): boolean {
  const code = ch.charCodeAt(0);
  // a-z, 0-9, hyphen, dot
  return (code >= 0x61 && code <= 0x7A) ||
         (code >= 0x30 && code <= 0x39) ||
         code === 0x2D || code === 0x2E;
}

// Validate domain against trusted list with homograph protection
function isDomainTrusted(domain: string): boolean {
  const normalizedInput = normalizeDomain(domain);

  // In strict mode, reject any non-ASCII characters
  if (STRICT_MODE) {
    for (const ch of normalizedInput) {
      if (ch.charCodeAt(0) > 127) {
        return false;
      }
    }
  }

  // Check each trusted domain
  for (const trusted of TRUSTED_DOMAINS) {
    const normalizedTrusted = normalizeDomain(trusted.trim());

    // Direct match
    if (normalizedInput === normalizedTrusted) {
      return true;
    }

    // Subdomain match: input ends with .trusted
    if (normalizedInput.endsWith('.' + normalizedTrusted)) {
      return true;
    }
  }

  return false;
}

// Confusable character detection - checks for known homoglyphs
function containsConfusables(domain: string): boolean {
  // Map of confusable Unicode characters to their ASCII lookalikes
  const confusableMap: Record<string, string> = {
    '\u0430': 'a', // Cyrillic а
    '\u0435': 'e', // Cyrillic е  
    '\u043E': 'o', // Cyrillic о
    '\u0440': 'p', // Cyrillic р
    '\u0441': 'c', // Cyrillic с
    '\u0443': 'y', // Cyrillic у
    '\u0445': 'x', // Cyrillic х
    '\u0455': 's', // Cyrillic ѕ
    '\u0456': 'i', // Cyrillic і
    '\u04BB': 'h', // Cyrillic һ
  };

  for (const ch of domain) {
    if (ch in confusableMap) {
      return true;
    }
  }
  return false;
}

// Main validation pipeline
function validateDeeplinkTarget(url: string): { valid: boolean; reason?: string } {
  const domain = extractDomain(url);

  if (!domain) {
    return { valid: false, reason: 'Invalid URL format' };
  }

  // Step 1: Check for confusable characters
  const hasConfusables = containsConfusables(domain);

  // Step 2: Validate against trusted domains
  const trusted = isDomainTrusted(domain);

  // Decision logic: if confusables detected but domain still matches trusted,
  // this indicates a homograph attack attempt
  if (hasConfusables && trusted) {
    // Log the attempt but still allow if normalization resolved it
    console.warn(`Potential homograph detected: ${domain}`);
    // After normalization, if it matches, the confusable resolved to trusted
    // This is actually safe - the normalization handled it
    return { valid: true };
  }

  if (!trusted) {
    return { valid: false, reason: 'Domain not in trusted list' };
  }

  return { valid: true };
}

// API endpoint for mobile deep link resolution
app.post('/api/v1/deeplink/resolve', (req: Request, res: Response) => {
  const { target_url, user_id, callback_token } = req.body as DeeplinkRequest;

  if (!target_url || !user_id || !callback_token) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate the callback token
  const expectedToken = generateHMAC(user_id + target_url, process.env.HMAC_SECRET || 'default-secret');
  if (!crypto.timingSafeEqual(Buffer.from(callback_token, 'hex'), Buffer.from(expectedToken, 'hex'))) {
    return res.status(403).json({ error: 'Invalid callback token' });
  }

  // Validate the target URL
  const validation = validateDeeplinkTarget(target_url);

  if (!validation.valid) {
    return res.status(400).json({ error: validation.reason });
  }

  // Generate redirect token for the mobile client
  const redirectToken = generateHMAC(target_url + Date.now().toString(), process.env.HMAC_SECRET || 'default-secret');

  return res.json({
    redirect_url: target_url,
    token: redirectToken,
    expires_in: 300
  });
});

export default app;
